//! Checks against the fixtures of `contracts/fixtures/unified-shell/`. They
//! were generated by an independent Python standard-library script from
//! published inputs (RFC 7748, RFC 8410, RFC 8032, RFC 9562) and synthetic
//! identifiers; here the crate and ring recompute every value.

use ring::{digest, hkdf, hmac};
use serde_json::Value;
use vodozemac::sas::Sas;
use vodozemac::{Curve25519PublicKey, Curve25519SecretKey};

use crate::b64;
use crate::framing::{self, Decoder, MessageLimit};
use crate::identity::Spki;
use crate::ids::{
    AccountId, CommandId, DerivedDomain, DeviceId, GrantId, HostId, derive_id, uuid_v8_from_digest,
};
use crate::journal::{CommandKind, CommandOutcome, CommandRequest, binding_digest};
use crate::pairing::transcript::{EphemeralKeys, Transcript, commitment};
use crate::pairing::{
    CancelCode, HASH, KEY_AGREEMENT, MAC_METHOD, PairingIdentity, PairingMessage, SAS_METHOD,
    decimals_from_bytes, establish, parse_ephemeral, window_closed_notice,
};
use crate::policy::{CeilingRefusal, HarnessId, Permissions, within_ceiling};
use crate::relay::{Inbound, RelayFrameV1, SequenceError};
use crate::tls::{ALPN, CHANNEL_BINDING_LABEL, CHANNEL_BINDING_LEN, ChannelRole};

const HOST_V1: &str =
    include_str!("../../../../contracts/fixtures/unified-shell/nano-host-v1.json");
const HOSTS_V1: &str =
    include_str!("../../../../contracts/fixtures/unified-shell/nano-hosts-v1.json");

fn host_v1() -> Value {
    serde_json::from_str(HOST_V1).expect("nano-host-v1.json")
}

fn hosts_v1() -> Value {
    serde_json::from_str(HOSTS_V1).expect("nano-hosts-v1.json")
}

fn text<'a>(value: &'a Value, key: &str) -> &'a str {
    value[key]
        .as_str()
        .unwrap_or_else(|| panic!("text field {key}"))
}

fn items<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    value[key]
        .as_array()
        .unwrap_or_else(|| panic!("array field {key}"))
}

fn hex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "{text}");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("hex"))
        .collect()
}

fn hex32(text: &str) -> [u8; 32] {
    hex(text).try_into().expect("32 bytes")
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

struct Length(usize);

impl hkdf::KeyType for Length {
    fn len(&self) -> usize {
        self.0
    }
}

/// RFC 5869 HKDF-SHA-256 without a salt, computed by ring.
fn hkdf_sha256(ikm: &[u8], info: &str, length: usize) -> Vec<u8> {
    let prk = hkdf::Salt::new(hkdf::HKDF_SHA256, &[]).extract(ikm);
    let info = [info.as_bytes()];
    let okm = prk.expand(&info, Length(length)).expect("length");
    let mut out = vec![0; length];
    okm.fill(&mut out).expect("fill");
    out
}

fn hmac_sha256(key: &[u8], input: &[u8]) -> Vec<u8> {
    hmac::sign(&hmac::Key::new(hmac::HMAC_SHA256, key), input)
        .as_ref()
        .to_vec()
}

#[test]
fn the_fixture_states_the_constants_of_this_crate() {
    let fixture = host_v1();
    assert_eq!(text(&fixture, "protocol"), crate::PROTOCOL);
    assert_eq!(text(&fixture, "alpn").as_bytes(), ALPN);
    assert_eq!(
        text(&fixture["channelBinding"], "label").as_bytes(),
        CHANNEL_BINDING_LABEL
    );
    assert_eq!(text(&fixture["channelBinding"], "context"), "");
    assert_eq!(
        fixture["channelBinding"]["length"].as_u64(),
        Some(CHANNEL_BINDING_LEN as u64)
    );
    assert_eq!(
        fixture["maxMessageBytes"].as_u64(),
        Some(u64::from(super::MAX_MESSAGE))
    );
    let limit = super::limit();
    for case in items(&fixture, "framing") {
        let payload = text(case, "payload").as_bytes();
        let framed = hex(text(case, "framedHex"));
        assert_eq!(framing::encode(payload, limit).expect("frame"), framed);
        let mut decoder = Decoder::new(limit);
        let mut messages = std::collections::VecDeque::new();
        decoder.push(&framed, &mut messages).expect("decode");
        assert_eq!(messages.pop_front().as_deref(), Some(payload));
    }
    assert!(MessageLimit::new(std::num::NonZeroU32::MIN).bytes() == 1);
}

#[test]
fn published_key_vectors_hold_for_the_selected_implementations() {
    let fixture = host_v1();
    for case in items(&fixture, "spki") {
        let spki = Spki::from_text(text(case, "text")).expect("SPKI");
        assert_eq!(
            to_hex(spki.ed25519_key()),
            text(case, "ed25519Hex"),
            "{}",
            text(case, "source")
        );
    }

    // RFC 7748 6.1 on vodozemac's X25519 (the primitive behind its SAS).
    let x25519 = &fixture["x25519"];
    let alice = Curve25519SecretKey::from_slice(&hex32(text(x25519, "alicePrivateHex")));
    let bob = Curve25519SecretKey::from_slice(&hex32(text(x25519, "bobPrivateHex")));
    let alice_public = Curve25519PublicKey::from(&alice);
    let bob_public = Curve25519PublicKey::from(&bob);
    assert_eq!(
        to_hex(alice_public.as_bytes()),
        text(x25519, "alicePublicHex")
    );
    assert_eq!(to_hex(bob_public.as_bytes()), text(x25519, "bobPublicHex"));
    let shared = alice.diffie_hellman(&bob_public).expect("contributory");
    assert_eq!(to_hex(shared.as_bytes()), text(x25519, "sharedHex"));
    let shared_back = bob.diffie_hellman(&alice_public).expect("contributory");
    assert_eq!(shared.as_bytes(), shared_back.as_bytes());

    let uuid = &fixture["uuidV8"];
    let namespace = uuid::Uuid::parse_str(text(uuid, "namespaceDns")).expect("namespace");
    let mut input = namespace.as_bytes().to_vec();
    input.extend_from_slice(text(uuid, "name").as_bytes());
    let digest = digest::digest(&digest::SHA256, &input);
    assert_eq!(
        uuid_v8_from_digest(digest.as_ref()).to_string(),
        text(uuid, "uuid")
    );
}

fn fixture_transcript(pairing: &Value) -> (Transcript, EphemeralKeys) {
    let identity: PairingIdentity =
        serde_json::from_value(pairing["identity"].clone()).expect("identity");
    let transcript = Transcript {
        identity,
        target_spki: Spki::from_text(text(pairing, "targetSpki")).expect("target SPKI"),
        controller_spki: Spki::from_text(text(pairing, "controllerSpki")).expect("controller SPKI"),
        channel_binding: hex32(text(pairing, "channelBindingHex")),
    };
    let keys = EphemeralKeys {
        target: b64::decode_array::<32>(text(pairing, "targetEphemeral")).expect("target key"),
        controller: b64::decode_array::<32>(text(pairing, "controllerEphemeral"))
            .expect("controller key"),
    };
    (transcript, keys)
}

#[test]
fn the_pairing_transcript_matches_the_independent_vectors() {
    let fixture = host_v1();
    let pairing = &fixture["pairing"];
    let messages = &pairing["messages"];
    let (transcript, keys) = fixture_transcript(pairing);
    assert_eq!(
        keys.target.as_slice(),
        hex(text(&fixture["x25519"], "alicePublicHex"))
    );

    let start = PairingMessage::Start {
        key_agreement: KEY_AGREEMENT.to_owned(),
        hash: HASH.to_owned(),
        mac: MAC_METHOD.to_owned(),
        sas: SAS_METHOD.to_owned(),
        account_id: transcript.identity.account_id.clone(),
        host_id: transcript.identity.host_id.clone(),
        controller_device_id: transcript.identity.controller_device_id.clone(),
    }
    .encode();
    assert_eq!(start, text(messages, "start").as_bytes());
    assert_eq!(
        b64::encode(&commitment(&keys.target, &start)),
        text(pairing, "commitment")
    );
    assert_eq!(transcript.sas_info(&keys), text(pairing, "sasInfo"));

    // The RFC 7748 secret through ring's HKDF and HMAC.
    let shared = hex(text(&fixture["x25519"], "sharedHex"));
    let sas_bytes: [u8; 6] = hkdf_sha256(&shared, &transcript.sas_info(&keys), 6)
        .try_into()
        .expect("6 bytes");
    assert_eq!(to_hex(&sas_bytes), text(pairing, "sasBytesHex"));
    let (first, second, third) = decimals_from_bytes(&sas_bytes);
    assert_eq!(
        serde_json::json!([first, second, third]),
        pairing["decimals"]
    );
    for (role, name) in [
        (ChannelRole::Target, "macTarget"),
        (ChannelRole::Controller, "macController"),
    ] {
        let vector = &pairing[name];
        let info = transcript.mac_info(role);
        assert_eq!(info, text(vector, "info"));
        assert_eq!(transcript.mac_input(role), text(vector, "input"));
        let mac_key = hkdf_sha256(&shared, &info, 32);
        assert_eq!(to_hex(&mac_key), text(vector, "keyHex"));
        let mac = hmac_sha256(&mac_key, transcript.mac_input(role).as_bytes());
        assert_eq!(b64::encode(&mac), text(vector, "mac"));
    }

    for (name, message) in messages.as_object().expect("messages") {
        let bytes = message.as_str().expect("message").as_bytes();
        let decoded =
            PairingMessage::decode(bytes).unwrap_or_else(|code| panic!("{name}: {code:?}"));
        assert_eq!(decoded.encode(), bytes, "{name}");
    }
    assert_eq!(
        window_closed_notice(),
        text(messages, "windowClosed").as_bytes()
    );
    assert!(matches!(
        PairingMessage::decode(text(messages, "cancel").as_bytes()),
        Ok(PairingMessage::Cancel {
            code: CancelCode::MismatchedSas
        })
    ));
    for case in items(pairing, "refusedMessages") {
        let bytes = text(case, "text").as_bytes();
        match text(case, "code") {
            "invalid-message" => assert_eq!(
                PairingMessage::decode(bytes),
                Err(CancelCode::InvalidMessage)
            ),
            "unknown-method" => {
                let Ok(PairingMessage::Start { mac, sas, .. }) = PairingMessage::decode(bytes)
                else {
                    panic!("a well-formed start");
                };
                assert!(mac != MAC_METHOD || sas != SAS_METHOD);
            }
            other => panic!("unexpected code {other}"),
        }
    }
}

#[test]
fn vodozemac_sas_output_is_hkdf_and_hmac_of_one_agreement() {
    // vodozemac hides the shared secret, so this checks the remaining step on
    // fresh keys: the SAS bytes are the first six bytes of the HKDF output
    // for the info, and the MAC is HMAC-SHA-256 keyed with 32 HKDF bytes for
    // the MAC info (vodozemac 0.11.2 `src/sas.rs`).
    let alice = Sas::new();
    let bob = Sas::new();
    let (alice_public, bob_public) = (alice.public_key(), bob.public_key());
    let alice = alice.diffie_hellman(bob_public).expect("alice");
    let bob = bob.diffie_hellman(alice_public).expect("bob");
    let info = "NANO_HOST_PAIRING_SAS_V1|probe";
    let okm = alice.bytes_raw(info, 32).expect("32 bytes");
    assert_eq!(okm, bob.bytes_raw(info, 32).expect("32 bytes"));
    let sas = alice.bytes(info);
    assert_eq!(sas.as_bytes().as_slice(), &okm[..6]);
    assert_eq!(sas.decimals(), decimals_from_bytes(sas.as_bytes()));
    assert_eq!(sas, bob.bytes(info));

    let mac_info = "NANO_HOST_PAIRING_MAC_V1|probe";
    let input = "MCowBQYDK2VwAyEAGb9ECWmEzf6FQbrBZ9w7lshQhqowtrbLDFw4rXAxZuE";
    let mac_key = alice.bytes_raw(mac_info, 32).expect("mac key");
    let mac = alice.calculate_mac(input, mac_info);
    assert_eq!(
        mac.as_bytes(),
        hmac_sha256(&mac_key, input.as_bytes()).as_slice()
    );
    assert!(bob.verify_mac(input, mac_info, &mac).is_ok());
    assert!(bob.verify_mac("other", mac_info, &mac).is_err());
}

#[test]
fn weak_ephemeral_keys_of_the_fixture_are_refused() {
    let fixture = host_v1();
    for case in items(&fixture, "weakEphemerals") {
        assert_eq!(text(case, "code"), "invalid-key");
        let encoded = b64::encode(&hex(text(case, "hex")));
        let sas = Sas::new();
        let own = sas.public_key().to_bytes();
        let result =
            parse_ephemeral(&encoded).and_then(|key| establish(sas, &own, &key).map(|_| ()));
        assert_eq!(result, Err(CancelCode::InvalidKey), "{}", text(case, "why"));
    }
    for case in items(&fixture, "decimal") {
        let bytes: [u8; 6] = hex(text(case, "bytesHex")).try_into().expect("6 bytes");
        let (first, second, third) = decimals_from_bytes(&bytes);
        assert_eq!(serde_json::json!([first, second, third]), case["decimals"]);
    }
}

#[test]
fn derived_identifiers_and_command_bindings_match_the_vectors() {
    let fixture = host_v1();
    for case in items(&fixture, "derivedIds") {
        let domain: DerivedDomain = serde_json::from_value(case["domain"].clone()).expect("domain");
        let grant = GrantId::parse(text(case, "grantId")).expect("grant");
        let command = CommandId::parse(text(case, "commandId")).expect("command");
        assert_eq!(
            derive_id(domain, &grant, &command).to_string(),
            text(case, "id")
        );
    }
    for case in items(&fixture, "commandBindings") {
        let kind: CommandKind = serde_json::from_value(case["kind"].clone()).expect("kind");
        let request = CommandRequest {
            command_id: CommandId::parse(text(case, "commandId")).expect("command"),
            kind,
            canonical: text(case, "canonical").as_bytes(),
        };
        let grant = GrantId::parse(text(case, "grantId")).expect("grant");
        assert_eq!(
            b64::encode(&binding_digest(&grant, &request)),
            text(case, "digest")
        );
    }
    for outcome in items(&fixture, "outcomes") {
        let parsed: CommandOutcome = serde_json::from_value(outcome.clone()).expect("outcome");
        assert_eq!(&serde_json::to_value(parsed).expect("json"), outcome);
    }
}

#[test]
fn ceiling_vectors_match_the_policy() {
    let fixture = host_v1();
    let rows = items(&fixture, "ceilings");
    assert_eq!(rows.len(), 4 * 4 * 2 * 2 * 2);
    for row in rows {
        let ceiling: Permissions = serde_json::from_value(row["ceiling"].clone()).expect("ceiling");
        let requested: Permissions =
            serde_json::from_value(row["requested"].clone()).expect("requested");
        let ceiling_harness = HarnessId::new(text(row, "ceilingHarness")).expect("harness");
        let harness = HarnessId::new(text(row, "harness")).expect("harness");
        let result = match within_ceiling(&ceiling_harness, ceiling, &harness, requested) {
            Ok(()) => "ok",
            Err(CeilingRefusal::Incomparable) => "incomparable",
            Err(CeilingRefusal::Exceeded) => "exceeded",
        };
        assert_eq!(result, text(row, "result"), "{row}");
    }
}

#[test]
fn relay_wire_examples_parse_with_the_crate_types() {
    let fixture = hosts_v1();
    let register = &fixture["putHostSelf"];
    assert_eq!(text(&register["request"], "protocol"), crate::PROTOCOL);
    assert!(Spki::from_text(text(&register["request"], "identitySpki")).is_ok());
    assert!(HostId::parse(text(&register["response"], "hostId")).is_ok());
    assert!(AccountId::parse(text(&register["response"], "accountId")).is_ok());
    assert!(GrantId::parse(text(&fixture["putHostGrant"], "grantId")).is_ok());
    assert!(
        DeviceId::parse(text(
            &fixture["putHostGrant"]["request"],
            "controllerDeviceId"
        ))
        .is_ok()
    );
    for host in items(&fixture["listHosts"]["response"], "hosts") {
        assert!(HostId::parse(text(host, "hostId")).is_ok());
        assert!(DeviceId::parse(text(host, "deviceId")).is_ok());
        assert!(Spki::from_text(text(host, "identitySpki")).is_ok());
        if let Some(grant) = host.get("grantId") {
            assert!(GrantId::parse(grant.as_str().expect("grant")).is_ok());
        }
    }

    let mut inbound = Inbound::new();
    for frame in items(&fixture["postFrames"]["request"], "frames") {
        let frame: RelayFrameV1 = serde_json::from_value(frame.clone()).expect("frame");
        assert!(inbound.accept(&frame).is_ok());
    }
    for event in items(&fixture, "streamEvents") {
        if text(event, "type") == "frames" {
            let mut inbound = Inbound::new();
            for frame in items(event, "frames") {
                let frame: RelayFrameV1 = serde_json::from_value(frame.clone()).expect("frame");
                assert!(inbound.accept(&frame).is_ok());
            }
        }
    }
    for case in items(&fixture, "refusedFrames") {
        let frame: RelayFrameV1 = serde_json::from_value(case["frame"].clone()).expect("frame");
        let refusal = Inbound::new().accept(&frame).expect_err(text(case, "why"));
        assert!(
            matches!(
                refusal,
                SequenceError::Data | SequenceError::OutOfOrder { .. }
            ),
            "{refusal:?}"
        );
    }
}
